N=colors.HexColor('#10233F');B=colors.HexColor('#1769AA');R=colors.HexColor('#C73535');O=colors.HexColor('#E68024');G=colors.HexColor('#23885B');I=colors.HexColor('#1D2939');M=colors.HexColor('#667085');P=colors.HexColor('#F3F6FA');L=colors.HexColor('#D8E0EA')
def rtl(x):return get_display(arabic_reshaper.reshape(str(x)),base_dir='R')
body=ParagraphStyle('b',fontName='A',fontSize=10,leading=16,alignment=TA_RIGHT,textColor=I,wordWrap='RTL',spaceAfter=4)
small=ParagraphStyle('s',parent=body,fontSize=8.1,leading=12.2,textColor=M)
h1s=ParagraphStyle('h1',fontName='AB',fontSize=18,leading=25,alignment=TA_RIGHT,textColor=N,wordWrap='RTL',spaceBefore=8,spaceAfter=7)
