h3s=ParagraphStyle('h3',fontName='AB',fontSize=11,leading=16,alignment=TA_RIGHT,textColor=N,wordWrap='RTL')
def p(x,st=body):return Paragraph(rtl(x),st)
def h1(x):return p(x,h1s)
def h2(x):return p(x,h2s)
def bullet(x,c=B):
 t=Table([[p(x),Paragraph('●',ParagraphStyle('d',fontName='Helvetica-Bold',fontSize=7,textColor=c,alignment=TA_CENTER))]],colWidths=[159*mm,6*mm]);t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),0),('TOPPADDING',(0,0),(-1,-1),1),('BOTTOMPADDING',(0,0),(-1,-1),1)]));return t
def note(t,x,c=B):
 z=Table([[p(t,h3s)],[p(x)]],colWidths=[165*mm]);z.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.Color(c.red,c.green,c.blue,alpha=.1)),('BOX',(0,0),(-1,-1),1,c),('LINEBEFORE',(0,0),(0,-1),4,c),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));return z
def tab(head,rows,w=None,sev=None):
 th=ParagraphStyle('th',parent=small,fontName='AB',textColor=colors.white,alignment=TA_CENTER);d=[[p(x,th)for x in head]]+[[p(x,small)for x in r]for r in rows];w=w or [165*mm/len(head)]*len(head);t=Table(d,colWidths=w,repeatRows=1);cmd=[('BACKGROUND',(0,0),(-1,0),N),('GRID',(0,0),(-1,-1),.45,L),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
 for i in range(1,len(d)):cmd.append(('BACKGROUND',(0,i),(-1,i),colors.white if i%2 else P))
 if sev is not None:
  for i,r in enumerate(rows,1):
   x=str(r[sev]);c=R if 'حرج'in x else O if 'عال'in x else B if 'متوسط'in x else G;cmd.append(('BACKGROUND',(sev,i),(sev,i),colors.Color(c.red,c.green,c.blue,alpha=.14)))
 t.setStyle(TableStyle(cmd));return t
class Doc(BaseDocTemplate):
 def __init__(self,path,title):
  super().__init__(path,pagesize=A4,rightMargin=22*mm,leftMargin=22*mm,topMargin=22*mm,bottomMargin=20*mm,title=title,author='Codex');self.titlear=title;self.addPageTemplates(PageTemplate(id='x',frames=Frame(self.leftMargin,self.bottomMargin,self.width,self.height,id='f'),onPage=self.pg))
 def pg(self,c,d):
  c.saveState();c.setFillColor(N);c.rect(0,A4[1]-10*mm,A4[0],10*mm,fill=1,stroke=0);c.setFont('A',8);c.setFillColor(colors.white);c.drawRightString(A4[0]-20*mm,A4[1]-6.5*mm,rtl(self.titlear));c.setStrokeColor(L);c.line(20*mm,14*mm,A4[0]-20*mm,14*mm);c.setFillColor(M);c.drawRightString(A4[0]-20*mm,9*mm,rtl(f'الصفحة {d.page}'));c.drawString(20*mm,9*mm,'ERP Alum - Technical Audit');c.restoreState()
def cover(title,sub):
 return [Spacer(1,23*mm),p(title,ParagraphStyle('cv',parent=h1s,fontSize=26,leading=36,alignment=TA_CENTER)),p(sub,ParagraphStyle('cs',parent=h1s,fontSize=18,leading=28,alignment=TA_CENTER,textColor=B)),Spacer(1,9*mm)]
